changeSet.sql:
UPDATE clinlims.localization_value lv SET origin = 'SYSTEM'
FROM clinlims.nce_type t
WHERE t.name_localization_id = lv.localization_id AND lv.value = t.name;
UPDATE clinlims.localization_value lv SET origin = 'SYSTEM'
FROM clinlims.nce_category c
WHERE c.name_localization_id = lv.localization_id AND lv.value = c.name;
UPDATE clinlims.localization_value lv SET origin = 'SYSTEM'
FROM clinlims.dictionary d
WHERE d.name_localization_id = lv.localization_id AND lv.value = d.dict_entry;
